        with urllib.request.urlopen(r) as f: return 200,f.read()
    except urllib.error.HTTPError as e: return e.code,e.read(),e.headers
def get(path):
    for i in range(200):
        res=raw("GET",path)
        if res[0]==200: return json.loads(res[1])
        if res[0]==404: return None
        if res[0]==401: tok[0]=None; continue
